using Microsoft.CodeAnalysis;

namespace Corpus.Generators;

/// <summary>Adds a file that returns default(Result) and declares a Result field nothing assigns.</summary>
[Generator(LanguageNames.CSharp)]
public sealed class DefaultEmittingGenerator : IIncrementalGenerator
{
    private const string Source =
        "// <auto-generated/>\n"
        + "namespace Corpus.Generated;\n"
        + "\n"
        + "public static class GeneratedFactory\n"
        + "{\n"
        + "    public static global::Spar.Result<global::SqlTool.CopyJobs.CopyPlan, global::SqlTool.CopyJobs.PlanError> Make() => default;\n"
        + "}\n"
        + "\n"
        + "public sealed partial class GeneratedHolder\n"
        + "{\n"
        + "    public global::Spar.Result<global::SqlTool.CopyJobs.CopyPlan, global::SqlTool.CopyJobs.PlanError> Last;\n"
        + "}\n";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(output => output.AddSource("Defaults.g.cs", Source));
    }
}
